/** The npm package name. One string, because three places print it. */
export const MCP_PACKAGE_NAME = "modelrefs-mcp";

/**
 * The server name an MCP client shows and namespaces tools under. Short
 * because the client already prefixes it; "modelrefs.get_model_evidence" is
 * what a user sees, so the tool names below carry no prefix of their own.
 */
export const MCP_SERVER_NAME = "modelrefs";

/** The env var the key is read from. Never a command-line argument: argv is
 *  visible to every process on the machine and in shell history, and an API
 *  key in a Cursor config file is bad enough without that. */
export const MCP_KEY_ENV = "MODELREFS_API_KEY";

export interface McpToolSpec {
  /** The tool name an agent calls. snake_case, no server prefix. */
  readonly name: string;
  /** Shown in a client's tool list. */
  readonly title: string;
  /**
   * What the agent reads to decide whether to call it. This is the single most
   * load-bearing string in the package: a tool an agent does not understand is
   * a tool an agent does not call, and nothing else in the product gets a
   * second chance to explain itself.
   */
  readonly description: string;
  /** The API path it speaks to, exactly as API_ENDPOINTS writes it. */
  readonly endpoint: string;
  readonly requiresKey: boolean;
}

export const MCP_TOOLS: readonly McpToolSpec[] = [
  {
    name: "list_covered_models",
    title: "List models with governed evidence",
    description:
      "List every model slug ModelRefs holds governed benchmark evidence for. Call this first: " +
      "coverage is a deliberate subset of the catalogue, and a model that is absent answers 404 " +
      "from the other tools rather than returning an empty result. Needs no API key.",
    endpoint: "/v1/coverage",
    requiresKey: false,
  },
  {
    name: "get_model_evidence",
    title: "Get governed evidence for a model",
    description:
      "Get the citations and governed benchmark runs ModelRefs holds for one model. Every run " +
      "carries its source, publisher, claim scope, methodology summary and - the part that " +
      "matters - what the publisher did NOT disclose. Use this instead of quoting a benchmark " +
      "number from memory: the number alone is not defensible, and the conditions it holds " +
      "under are what makes it usable in a decision.",
    endpoint: "/v1/models/{slug}/evidence",
    requiresKey: true,
  },
  {
    name: "check_model_lifecycle",
    title: "Check whether a model is being retired",
    description:
      "Check whether a model is deprecated, when it retires and what replaces it. Pass the " +
      "dated snapshot id the code actually pins (for example gpt-4o-2024-05-13) rather than the " +
      "family slug: providers retire individual snapshots months before the family and name a " +
      "different replacement for them, so a family-level answer is wrong by months for whoever " +
      "pinned early. A model with no reviewed record answers 404, which means unknown, not active.",
    endpoint: "/v1/models/{slug}/lifecycle",
    requiresKey: true,
  },
  {
    name: "compare_models",
    title: "Compare two or more models on comparable benchmark runs",
    description:
      "Compare models on benchmarks where their runs are actually comparable. Two runs are " +
      "paired only when the benchmark, the metric and the task subset all match; runs that " +
      "share a benchmark name but differ in metric or subset are reported as incomparable " +
      "rather than ranked, because putting tau-bench Retail beside tau2-bench telecom reads as " +
      "a twenty-point capability gap that is mostly a domain difference. Returns the pairings, " +
      "the gap on each, and every benchmark that could not be compared and why.",
    endpoint: "/v1/models/{slug}/evidence",
    requiresKey: true,
  },
];

/** The tool for a name, or undefined. */
export function mcpTool(name: string): McpToolSpec | undefined {
  return MCP_TOOLS.find((t) => t.name === name);
}

